var n=`0521-tahchin`;var t=`world-0521`;var a=`IR`;var r=`western-asia`;var o=4;var s=114;var l={en:`Tahchin`,ua:`Тачин`};var g={en:`A traditional dish from Iran, centered on basmati rice, chicken thigh, plain yogurt, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: рис басматі, куряче стегно, натуральний йогурт, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var c=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`basmati-rice`,420,`g`],[`water`,1300,`ml`]]},{en:`Poach the chicken in gently simmering water until fully cooked, then shred and cool before layering.`,ua:`Відваріть курятину у воді за слабкого кипіння до повної готовності, розберіть на волокна й остудіть перед формуванням шарів.`,t:[`poaching`],m:28,i:[[`chicken-thigh`,580,`g`],[`water`,450,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`plain-yogurt`,260,`g`],[`chicken-egg`,2,`pcs`],[`saffron-threads`,.4,`g`],[`sunflower-oil`,70,`ml`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:11,i:[[`unsalted-butter`,60,`g`]]},{en:`Pack the saffron-yogurt rice and cooked chicken into a well-oiled oven dish; bake until a deeply golden crust forms before turning out.`,ua:`Утрамбуйте шафраново-йогуртовий рис із готовою курятиною в змащену форму й запікайте до глибокої золотистої скоринки, тоді переверніть на таріль.`,t:[`roasting`],m:55,i:[]}];var d={slug:n,id:t,country:`IR`,region:r,servings:4,minutes:114,title:l,text:g,steps:c};export{a as country,d as default,t as id,s as minutes,r as region,o as servings,n as slug,c as steps,g as text,l as title};